Rules.InvariantScript:
Set(varAppView, "MilestoneAdmin");
Set(varPageKey, "MILESTONE_ADMIN");
Set(varPageTitle, "Milestone Administration");
Set(varPageSubtitle, "Manage subsystem partial delivery packages");
If(
    !varDPA_Loaded && !varDPA_Loading && !IsBlank(varProjectId),
    Select(btnDPA_LoadPackages)
)

Set(varDPA_Search, "");
Set(varDPA_FilterStage, "");
Set(varDPA_FilterRisk, "");
Reset(txtDPA_Search);
Reset(txtDPA_FilterStage);
Reset(txtDPA_FilterRisk);
Select(btnDPA_LoadPackages)

Set(varDPA_Loading, true);
Set(varDPA_Error, "");
Set(varDPA_Loaded, false);
Set(varGlobalLoading, true);
Set(varGlobalLoadingMsg, "Loading Delivery Packages");
Set(varGlobalLoadingSubMsg, "Reading subsystem partial delivery milestones");
Set(varGlobalLoadingScope, "MILESTONE_ADMIN");

Clear(colDPA_Packages);
Clear(colDPA_SelectedRows);

If(
    IsBlank(varProjectId),
    Notify("Please select a project first.", NotificationType.Warning);
    Set(varDPA_Loading, false);
    Set(varGlobalLoading, false);
    Set(varGlobalLoadingMsg, "");
    Set(varGlobalLoadingSubMsg, "");
    Set(varGlobalLoadingScope, "");
    Exit()
);

IfError(
    With(
        {
            resp: Warroom_Pulse_GetDeliveryPackages.Run(
                Value(varProjectId),
                If(IsBlank(varDPA_Search), "", Text(varDPA_Search)),
                If(IsBlank(varDPA_FilterStage), "", Text(varDPA_FilterStage)),
                If(IsBlank(varDPA_FilterRisk), "", Text(varDPA_FilterRisk))
            )
        },
        With(
            { arr: Table(ParseJSON(Coalesce(resp.result, "[]"))) },
            ClearCollect(
                colDPA_Packages,
                ForAll(
                    arr,
                    With(
                        { r: ThisRecord.Value },
                        {
                            DeliveryPackageId: Value(Text(r.DeliveryPackageId)),
                            ProjectId: Value(Text(r.ProjectId)),
                            SubsystemCode: Text(r.SubsystemCode),
                            PackageCode: Text(r.PackageCode),
                            PackageName: Text(r.PackageName),
                            DeliveryStage: Text(r.DeliveryStage),
                            Discipline: Text(r.Discipline),
                            PlannedDate: If(IsBlank(Text(r.PlannedDate)) || Text(r.PlannedDate) = "null", Blank(), DateValue(Text(r.PlannedDate))),
                            ForecastDate: If(IsBlank(Text(r.ForecastDate)) || Text(r.ForecastDate) = "null", Blank(), DateValue(Text(r.ForecastDate))),
                            ActualDate: If(IsBlank(Text(r.ActualDate)) || Text(r.ActualDate) = "null", Blank(), DateValue(Text(r.ActualDate))),
                            OwnerEmail: Text(r.OwnerEmail),
                            CompletionPct: If(IsBlank(Text(r.CompletionPct)) || Text(r.CompletionPct) = "null", 0, Value(Text(r.CompletionPct))),
                            OpenTasks: If(IsBlank(Text(r.OpenTasks)) || Text(r.OpenTasks) = "null", 0, Value(Text(r.OpenTasks))),
                            OpenPunches: If(IsBlank(Text(r.OpenPunches)) || Text(r.OpenPunches) = "null", 0, Value(Text(r.OpenPunches))),
                            RiskStatus: Text(r.RiskStatus),
                            ReadinessScore: If(IsBlank(Text(r.ReadinessScore)) || Text(r.ReadinessScore) = "null", 0, Value(Text(r.ReadinessScore))),
                            Notes: Text(r.Notes),
                            LastUpdatedOn: If(IsBlank(Text(r.LastUpdatedOn)) || Text(r.LastUpdatedOn) = "null", Blank(), DateTimeValue(Text(r.LastUpdatedOn)))
                        }
                    )
                )
            )
        )
    ),
    Set(varDPA_Error, FirstError.Message);
    Notify("Error loading Delivery Packages: " & varDPA_Error, NotificationType.Error)
);

Set(varDPA_LastRefresh, Now());
Set(varDPA_Loaded, true);
Set(varDPA_Loading, false);
Set(varGlobalLoading, false);
Set(varGlobalLoadingMsg, "");
Set(varGlobalLoadingSubMsg, "");
Set(varGlobalLoadingScope, "")

If(
    IsBlank(varDPA_SelectedPackage),
    Notify("Select a delivery package first.", NotificationType.Warning);
    Exit()
);

Set(varDPA_Saving, true);
Set(varGlobalLoading, true);
Set(varGlobalLoadingMsg, "Saving Delivery Package");
Set(varGlobalLoadingSubMsg, "Updating planned, forecast and actual dates");
Set(varGlobalLoadingScope, "MILESTONE_ADMIN");

IfError(
    Warroom_Pulse_UpsertDeliveryPackage.Run(
        Value(varProjectId),
        Value(varDPA_SelectedPackage.DeliveryPackageId),
        Text(varDPA_SelectedPackage.SubsystemCode),
        Text(varDPA_SelectedPackage.PackageCode),
        Text(txtDPA_EditPlanned.Text),
        Text(txtDPA_EditForecast.Text),
        Text(txtDPA_EditActual.Text),
        Text(txtDPA_EditOwner.Text),
        Value(txtDPA_EditCompletion.Text),
        Text(txtDPA_EditNotes.Text)
    ),
    Notify("Error saving Delivery Package: " & FirstError.Message, NotificationType.Error);
    Set(varDPA_Saving, false);
    Set(varGlobalLoading, false);
    Set(varGlobalLoadingMsg, "");
    Set(varGlobalLoadingSubMsg, "");
    Set(varGlobalLoadingScope, "");
    Exit()
);

Notify("Delivery package updated.", NotificationType.Success);
Set(varDPA_Saving, false);
Set(varGlobalLoading, false);
Set(varGlobalLoadingMsg, "");
Set(varGlobalLoadingSubMsg, "");
Set(varGlobalLoadingScope, "");
Select(btnDPA_LoadPackages)
